    const circuits=new ProviderCircuitBreakerService(store,{failureThreshold:1,cooldownMs:60_000});let catalogCalls=0;let staffCalls=0;const factory=()=>({listAppointmentServices:async()=>{catalogCalls+=1;return[]},listBookableStaff:async()=>{staffCalls+=1;throw Object.assign(new Error('staff catalog unavailable'),{status:503})}})
    const first=new SquareSyncService(store,cipher,new AuditService(store),'sandbox',factory,undefined,circuits);const second=new SquareSyncService(store,cipher,new AuditService(store),'sandbox',factory,undefined,circuits)
    await expect(first.sync(context)).rejects.toThrow('staff catalog unavailable');await expect(second.sync(context)).rejects.toMatchObject({code:'PROVIDER_CIRCUIT_OPEN'})
