describe('Square token lifecycle',()=>{
  it('refreshes an expiring token and encrypts the rotated credentials',async()=>{
    const store=new MemoryStore();const cipher=new CredentialCipher(Buffer.alloc(32,10).toString('base64'));const context={tenantId:'tenant-one',locationId:'location-one',userId:'user-one',role:'service' as const};const now=new Date().toISOString()
    await store.saveIntegrationAccount({id:randomUUID(),tenantId:context.tenantId,locationId:context.locationId,provider:'square',externalId:'merchant-one',encryptedCredentials:cipher.encrypt({accessToken:'old-access',refreshToken:'old-refresh'}),status:'active',tokenExpiresAt:new Date(Date.now()+60_000).toISOString(),createdAt:now,updatedAt:now})
    const tokens=new SquareTokenService(store,cipher,undefined,async(refreshToken)=>{expect(refreshToken).toBe('old-refresh');return{accessToken:'new-access',refreshToken:'new-refresh',expiresAt:new Date(Date.now()+30*86_400_000).toISOString()}})
    expect(await tokens.getAccessToken(context)).toBe('new-access')
    const account=await store.getIntegrationAccount(context,'square');expect(cipher.decrypt(account!.encryptedCredentials)).toEqual({accessToken:'new-access',refreshToken:'new-refresh'});expect(await store.getAudit(context)).toEqual([expect.objectContaining({userId:'user-one',action:'integration.square_token_refreshed',entityId:account!.id,input:{provider:'square'},result:{provider:'square',status:'active',credentialRotation:'completed'}})])
  })

  it('single-flights concurrent refreshes and lets both callers reuse the rotation',async()=>{
    const store=new MemoryStore();const cipher=new CredentialCipher(Buffer.alloc(32,11).toString('base64'));const context={tenantId:'tenant-one',locationId:'location-one',userId:'service-one',role:'service' as const};const now=new Date().toISOString();let calls=0
    await store.saveIntegrationAccount({id:randomUUID(),tenantId:context.tenantId,locationId:context.locationId,provider:'square',externalId:'merchant-one',encryptedCredentials:cipher.encrypt({accessToken:'old-access',refreshToken:'old-refresh'}),status:'active',tokenExpiresAt:new Date(Date.now()+60_000).toISOString(),createdAt:now,updatedAt:now})
    const refresher=async(refreshToken:string)=>{calls+=1;expect(refreshToken).toBe('old-refresh');await Promise.resolve();return{accessToken:'shared-access',refreshToken:'shared-refresh',expiresAt:new Date(Date.now()+30*86_400_000).toISOString()}}
    const first=new SquareTokenService(store,cipher,undefined,refresher);const second=new SquareTokenService(store,cipher,undefined,refresher)
    expect(await Promise.all([first.getAccessToken(context),second.getAccessToken(context)])).toEqual(['shared-access','shared-access']);expect(calls).toBe(1)
    const account=await store.getIntegrationAccount(context,'square');expect(cipher.decrypt(account!.encryptedCredentials)).toEqual({accessToken:'shared-access',refreshToken:'shared-refresh'});const evidence=JSON.stringify(await store.getAudit(context));expect(JSON.parse(evidence)).toHaveLength(1);expect(evidence).toContain('integration.square_token_refreshed');expect(evidence).not.toContain('shared-access');expect(evidence).not.toContain('shared-refresh')
  })

  it('pauses a workflow on refresh failure and resumes it after tenant-bound OAuth reconnects',async()=>{
    const store=new MemoryStore();const cipher=new CredentialCipher(Buffer.alloc(32,12).toString('base64'));const context={tenantId:'tenant-one',locationId:'location-one',userId:'service-one',role:'service' as const};const now=new Date().toISOString();let refreshCalls=0
    await store.saveIntegrationAccount({id:randomUUID(),tenantId:context.tenantId,locationId:context.locationId,provider:'square',externalId:'merchant-one',encryptedCredentials:cipher.encrypt({accessToken:'expired-access',refreshToken:'expired-refresh'}),status:'active',tokenExpiresAt:new Date(Date.now()+60_000).toISOString(),createdAt:now,updatedAt:now})
    const tokens=new SquareTokenService(store,cipher,undefined,async()=>{refreshCalls+=1;throw Object.assign(new Error('provider detail must not persist'),{statusCode:503})})
    const job:WorkflowJob={id:randomUUID(),tenantId:context.tenantId,locationId:context.locationId,workflowType:'conversation_turn',correlationId:'conversation-one',causationEventId:'message-one',dedupeKey:'square-refresh-pause-one',runAt:now,status:'pending',attempts:0,maxAttempts:1,payload:{conversationId:'conversation-one',messageId:'message-one'},createdAt:now,updatedAt:now};await store.enqueueWorkflowJob(job)
    const engine=new WorkflowEngine(store,{execute:async value=>{await tokens.getAccessToken({tenantId:value.tenantId,locationId:value.locationId,userId:`workflow:${value.workflowType}`,role:'service'})}},'square-refresh-worker')
    expect(await engine.tick()).toEqual({dispatched:0,processed:1});expect(refreshCalls).toBe(1);expect(await store.listWorkflowJobs(context)).toEqual([expect.objectContaining({id:job.id,status:'paused',attempts:1,lastError:'integration:square:Square OAuth token refresh failed'})]);expect(await store.listWorkflowDeadLetters(context)).toEqual([]);expect(await store.listApprovalRequests(context)).toEqual([expect.objectContaining({requestType:'integration_reconnect',entityType:'integration_account',payload:{provider:'square'}})])
    const oauth=new SquareOAuthService(store,cipher,{applicationId:'sandbox-app-id',applicationSecret:'sandbox-secret',redirectUri:'http://127.0.0.1:4100/oauth/square/callback',environment:'sandbox'},undefined,async()=>({accessToken:'reconnected-access',refreshToken:'reconnected-refresh',merchantId:'merchant-one',expiresAt:new Date(Date.now()+30*86_400_000).toISOString()}));const owner={...context,userId:'owner-one',role:'owner' as const};const state=new URL((await oauth.begin(owner)).authorizationUrl).searchParams.get('state')!;await oauth.complete('authorization-code',state)
    expect(await store.listWorkflowJobs(context)).toEqual([expect.objectContaining({id:job.id,status:'pending',attempts:0})]);expect(await engine.tick()).toEqual({dispatched:2,processed:1});expect(refreshCalls).toBe(1);expect(await store.listWorkflowJobs(context)).toEqual([expect.objectContaining({id:job.id,status:'completed',attempts:1})])
  })

  it('keeps interactive refresh failures as fail-closed API errors',async()=>{
    const store=new MemoryStore();const cipher=new CredentialCipher(Buffer.alloc(32,13).toString('base64'));const context={tenantId:'tenant-one',locationId:'location-one',userId:'operator-one',role:'operator' as const};const now=new Date().toISOString();let calls=0;await store.saveIntegrationAccount({id:randomUUID(),tenantId:context.tenantId,locationId:context.locationId,provider:'square',externalId:'merchant-one',encryptedCredentials:cipher.encrypt({accessToken:'expired-access',refreshToken:'expired-refresh'}),status:'active',tokenExpiresAt:new Date(Date.now()+60_000).toISOString(),createdAt:now,updatedAt:now});const tokens=new SquareTokenService(store,cipher,undefined,async()=>{calls+=1;throw new Error('refresh unavailable')});await expect(tokens.getAccessToken(context)).rejects.toMatchObject({code:'SQUARE_TOKEN_REFRESH_FAILED',statusCode:502});await expect(tokens.getAccessToken(context)).rejects.toMatchObject({code:'SQUARE_TOKEN_REFRESH_FAILED',statusCode:502});expect(calls).toBe(2);expect(await store.listWorkflowJobs(context)).toEqual([]);expect(await store.listApprovalRequests(context)).toHaveLength(1);const evidence=JSON.stringify(await store.getOutbox(context));expect(JSON.parse(evidence)).toEqual([expect.objectContaining({eventType:'approval.requested',payload:expect.objectContaining({requestType:'integration_reconnect',entityType:'integration_account'})})]);expect(evidence).not.toContain('expired-access');expect(evidence).not.toContain('expired-refresh');expect(evidence).not.toContain('refresh unavailable')
  })
})

