    for(const [clientId,contactTo] of [['client-one','+447700900111'],['client-two','+447700900222']] as const){await consent.record(context,{clientId,channel:'sms',purpose:'transactional',status:'opted_in',captureMethod:'waitlist_form',disclosureVersion:'v1'});await waitlist.join(context,{clientId,contactTo,serviceId:'service-one',staffIds:['staff-one'],windowStart,windowEnd,timezone:'Europe/London'})}
    await events.ingest(context,{eventId:randomUUID(),eventType:'appointment.cancelled',occurredAt:new Date().toISOString(),correlationId:'cancelled-booking',schemaVersion:1,payload:{serviceId:'service-one',staffId:'staff-one',startsAt,priceMinor:18500,currency:'GBP'}})
    const engine=new WorkflowEngine(store,new CoreWorkflowHandler(messages,events,waitlist),'waitlist-worker');await engine.tick();expect(sent).toEqual(['+447700900111'])
    const firstMatch=(await store.getOutbox(context)).find(value=>value.eventType==='waitlist.match_found')!;const firstOfferId=String(firstMatch.payload.offerId);expect(await store.getWaitlistOffer(context,firstOfferId)).toMatchObject({status:'offered',sentAt:expect.any(String),providerMessageId:'message-1'});expect((await store.listWorkflowJobs(context)).find(value=>value.payload.offerId===firstOfferId)).toMatchObject({workflowType:'waitlist_match',runAt:firstMatch.payload.expiresAt,payload:expect.objectContaining({phase:'offer_expiry'})});expect((await store.getAudit(context)).filter(value=>value.action==='waitlist.offer_sent')).toEqual([expect.objectContaining({entityId:firstOfferId,result:{status:'offered',providerMessageId:'message-1',expiryScheduled:true}})]);await waitlist.respond(context,firstOfferId,false);expect(await store.getWaitlistOffer(context,firstOfferId)).toMatchObject({status:'declined',respondedAt:expect.any(String)});expect((await store.getOutbox(context)).filter(value=>value.eventType==='waitlist.offer_responded')).toEqual([expect.objectContaining({payload:expect.objectContaining({offerId:firstOfferId,status:'declined',accepted:false,continuationScheduled:true})})]);expect((await store.getAudit(context)).filter(value=>value.action==='waitlist.offer_declined')).toEqual([expect.objectContaining({entityId:firstOfferId,result:{status:'declined',continuationScheduled:true}})]);expect((await store.listWorkflowJobs(context)).find(value=>value.dedupeKey.endsWith(`:declined:${firstOfferId}`))).toMatchObject({status:'pending',payload:expect.objectContaining({phase:'continuation'})});await engine.tick();expect(sent).toEqual(['+447700900111','+447700900222'])
    const secondMatch=(await store.getOutbox(context)).filter(value=>value.eventType==='waitlist.match_found').at(-1)!;const secondOfferId=String(secondMatch.payload.offerId);expect(await store.getWaitlistOffer(context,secondOfferId)).toMatchObject({sentAt:expect.any(String),providerMessageId:'message-2'});expect((await store.getAudit(context)).filter(value=>value.action==='waitlist.offer_sent')).toHaveLength(2);await waitlist.respond(context,secondOfferId,true);expect((await store.getOutbox(context)).filter(value=>value.eventType==='waitlist.offer_responded')).toEqual([expect.objectContaining({payload:expect.objectContaining({offerId:secondOfferId,status:'accepted',accepted:true,continuationScheduled:false})})]);expect((await store.getAudit(context)).filter(value=>value.action==='waitlist.offer_accepted')).toEqual([expect.objectContaining({entityId:secondOfferId,result:{status:'accepted',continuationScheduled:false}})])
    const bookings=new BookingService(store,events,audit);const hold=await bookings.createHold(context,{clientId:'client-two',serviceId:'service-one',staffId:'staff-one',startsAt,timezone:'Europe/London',expectedPriceMinor:18500,currency:'GBP',provider:'local',contactTo:'+447700900222'});const bookingInput={holdId:hold.id,clientId:'client-two',confirmationToken:hold.confirmationToken,explicitConfirmation:true as const,expectedPriceMinor:18500,currency:'GBP',idempotencyKey:'waitlist-booking-00001',waitlistOfferId:secondOfferId};const result=await bookings.book(context,bookingInput)
    expect(result.booking).toMatchObject({priceMinor:18500,waitlistOfferId:secondOfferId});expect(await store.listRevenueAttribution(context)).toEqual([expect.objectContaining({bookingId:result.booking.id,waitlistOfferId:secondOfferId,amountMinor:18500,currency:'GBP',attributionType:'waitlist_fill',evidence:'accepted_waitlist_offer'})]);expect(await store.getWaitlistOffer(context,secondOfferId)).toMatchObject({status:'booked'});expect(await store.listRecoveryCases(context)).toEqual([expect.objectContaining({recoveryType:'waitlist_fill',status:'resolved',resultBookingId:result.booking.id})]);expect((await store.getOutbox(context)).filter(value=>value.eventType==='revenue.recovered')).toEqual([expect.objectContaining({correlationId:result.booking.id,payload:expect.objectContaining({waitlistOfferId:secondOfferId,attributionType:'waitlist_fill',evidence:'accepted_waitlist_offer'})})]);expect((await store.getAudit(context)).filter(value=>value.action==='revenue.attributed')).toEqual([expect.objectContaining({input:{workflowJobId:expect.any(String),attributionType:'waitlist_fill',evidence:'accepted_waitlist_offer'},result:{bookingRecorded:true,sourceRecorded:true,amountMinor:18500,currency:'GBP'}})]);expect((await bookings.book(context,bookingInput)).duplicate).toBe(true);expect(await store.listRevenueAttribution(context)).toHaveLength(1);expect((await store.getOutbox(context)).filter(value=>value.eventType==='revenue.recovered')).toHaveLength(1);expect((await store.getAudit(context)).filter(value=>value.action==='revenue.attributed')).toHaveLength(1);const report=await new RevenueReportService(store).weekly(context,new Date(Date.now()-86_400_000).toISOString(),new Date(Date.now()+86_400_000).toISOString());expect(report.observed).toMatchObject({verifiedRecoveredRevenueMinorByCurrency:{GBP:18500},recoveredBookings:1,recoveryCasesResolved:1});expect(report.dataQuality.estimatedRevenueIncluded).toBe(false)
