fferDeliveryWithEvidence(context,offer.id,'message-claim',expiryJob,{auditId:randomUUID(),eventId:randomUUID(),userId:context.userId,occurredAt:createdAt});await store.respondWaitlistOfferWithEvidence(context,offer.id,true,undefined,{auditId:randomUUID(),eventId:randomUUID(),userId:context.userId,occurredAt:new Date().toISOString()});const hold:AppointmentHold={id:randomUUID(),tenantId:context.tenantId,locationId:context.locationId,clientId:entry.clientId,serviceId:'service-one',staffId:'staff-one',startsAt,timezone:'Europe/London',expectedPriceMinor:18500,currency:'GBP',provider:'square',providerDetails:{provider:'square',customerId:'square-client-claim',serviceVariationVersion:'1',durationMinutes:60},confirmationToken:'waitlist-claim-token',expiresAt:new Date(Date.now()+600_000).toISOString(),status:'active'};await store.saveHold(hold);const gateway:BookingGateway={searchAvailability:async()=>[],validateHold:async()=>hold.providerDetails!,createBooking:async()=>{throw new Error('provider unavailable')},cancelBooking:async()=>({provider:'square',id:'unused'}),rescheduleBooking:async()=>({provider:'square',id:'unused'})};const bookings=new BookingService(store,events,audit,gateway);const failedKey='waitlist-provider-failure';await expect(bookings.book(context,{holdId:hold.id,clientId:entry.clientId,confirmationToken:hold.confirmationToken,explicitConfirmation:true,expectedPriceMinor:18500,currency:'GBP',idempotencyKey:failedKey,waitlistOfferId:offer.id})).rejects.toThrow('provider unavailable');expect(await store.getHold(context,hold.id)).toMatchObject({status:'active'});expect(await store.getWaitlistOffer(context,offer.id)).toMatchObject({status:'accepted'});const claimKey='waitlist-expiry-race';await store.claimHold(context,hold.id,claimKey,offer.id);expect(await store.getWaitlistOffer(context,offer.id)).toMatchObject({status:'booking',bookingAttemptKey:claimKey,bookingHoldId:hold.id});await expect(waitlist.process(expiryJob)).rejects.toMatchObject({message:'Waitlist expiry delayed while a confirmed booking is in progress',runAt:expect.any(String)});expect((await store.getOutbox(context)).filter(value=>value.eventType==='waitlist.offer_expired')).toHaveLength(0);await store.releaseHold(context,hold.id,claimKey,offer.id);expect(await store.getWaitlistOffer(context,offer.id)).toMatchObject({status:'accepted'});const continuation={...expiryJob,id:randomUUID(),causationEventId:offer.workflowJobId,dedupeKey:`${context.tenantId}:${context.locationId}:waitlist_match:${offer.correlationId}:expired:${offer.id}`,runAt:offer.expiresAt,payload:{...source.payload,phase:'continuation'},createdAt:offer.expiresAt,updatedAt:offer.expiresAt};const expired=await store.expireWaitlistOfferWithEvidence(context,offer.id,continuation,{auditId:randomUUID(),eventId:randomUUID(),userId:context.userId,occurredAt:offer.expiresAt});expect(expired?.offer).toMatchObject({status:'expired',expiredAt:offer.expiresAt});expect(await store.getWaitlistEntry(context,entry.id)).toMatchObject({status:'active'})
